	for i := uint(0); i < count; i++ {
		deviceInfo, err := deps.getDeviceInfo(i)
		if err != nil {
			log.Printf("(DCGM) Error getting device information: %s", err)
			return
		}

		uuids[deviceInfo.UUID] = i
	}
}

